import {Link, Label} from '@primer/react'
import {clsx} from 'clsx'
import styles from './MeteredEnterpriseServerLicense.module.css'

import type {ServerLicense} from '../types/server-licenses'
import {pluralize} from '../utils/text'

export interface Props {
  meteredServerLicensesBaseUrl: string
  onRegenerate: (license: ServerLicense) => void
  serverLicense: ServerLicense
  showDownloadLink?: boolean
  showRegenerateLink?: boolean
  isCountryBlocked?: boolean
}

export function MeteredEnterpriseServerLicense({
  serverLicense,
  meteredServerLicensesBaseUrl,
  onRegenerate,
  showDownloadLink = false,
  showRegenerateLink = false,
  isCountryBlocked = false,
}: Props) {
  const expiresAt = new Date(Date.parse(serverLicense.expires_at))

  const downloadLink = `${meteredServerLicensesBaseUrl}/${serverLicense.reference_number}`

  return (
    <div
      className="Box-row d-flex flex-column flex-sm-row flex-sm-items-center color-fg-muted gap-2"
      data-testid="server-license-row"
    >
      <div className={clsx('Box-title flex-1 ml-1', styles.serverKeyIdentifier)}>
        {serverLicense.reference_number}
        <div className="text-small text-normal">Valid until {expiresAt.toDateString()}</div>
      </div>
      <div
        className="d-flex flex-1 flex-wrap flex-items-center flex-justify-between gap-2"
        data-testid="server-license-metadata"
      >
        <div>
          <b>{serverLicense.seats}</b> {pluralize(serverLicense.seats, 'license', false)}
        </div>
        <div className="d-flex flex-wrap flex-items-center gap-2">
          {isCountryBlocked && showDownloadLink ? (
            <Label variant="secondary" data-testid="spammy-label">
              Not available in your country
            </Label>
          ) : (
            showDownloadLink && (
              <Link href={downloadLink} className="Link--inTextBlock" download>
                Download
              </Link>
            )
          )}
          {showRegenerateLink && (
            <Link
              as="button"
              className="Link--inTextBlock"
              onClick={() => onRegenerate(serverLicense)}
              data-testid="regenerate-license-link"
              type="button"
            >
              Regenerate
            </Link>
          )}
        </div>
      </div>
    </div>
  )
}
