import {Link, Spinner, Banner} from '@primer/react'
import {ServerIcon} from '@primer/octicons-react'
import {clsx} from 'clsx'
import type {Dispatch, SetStateAction} from 'react'
import {useEffect, useMemo, useRef, useState} from 'react'
import styles from './MeteredEnterpriseServerLicenses.module.css'

import {SummaryCard} from '@github-ui/licensing-common/components/SummaryCard'
import {SummaryCardBanner} from '@github-ui/licensing-common/components/SummaryCardBanner'

import {MeteredEnterpriseServerLicense} from './components/MeteredEnterpriseServerLicense'
import {useExportStatus} from './hooks/use-export-status'
import {ExportJobState} from './types/export-job-state'
import {pluralize} from './utils/text'
import {getLicenseExpirationStatus} from './utils/license-expiration'

import type {Business} from './types/business'
import type {ServerLicense} from './types/server-licenses'
import {verifiedFetch} from '@github-ui/verified-fetch'

export interface Props {
  business: Business
  isOwner: boolean
  isGhasBundled: boolean
  enableGhasBundleMismatchWarning: boolean
  consumedEnterpriseLicenses: number
  isStafftools?: boolean
  serverLicenses: ServerLicense[]
  auditLogQueryUrl?: string
  isCountryBlocked?: boolean
}

const GeneratingLicense = ({consumedEnterpriseLicenses}: {consumedEnterpriseLicenses: number}) => (
  <div className="Box-footer d-flex flex-items-center flex-column border-0 tmp-p-5" data-testid="generating-license">
    <Spinner />
    <div className="tmp-pt-3">
      Generating a new license for {pluralize(consumedEnterpriseLicenses, 'Enterprise Cloud user')}.
    </div>
  </div>
)

type BannerVariant = 'info' | 'warning' | 'critical' | 'success'

const MESLBanner = ({
  showBanner,
  bannerVariant,
  bannerMessage,
  bannerLink,
  handleCreateLicense,
  setShowBanner,
}: {
  showBanner: boolean
  bannerVariant?: BannerVariant
  bannerMessage?: string
  bannerLink?: string
  handleCreateLicense: () => Promise<void>
  setShowBanner: Dispatch<SetStateAction<boolean>>
}) => {
  // focus the banner when it is shown, if it is a success or critical (error) banner
  const focusRef = useFocusOnShow(
    showBanner && (bannerVariant === 'success' || bannerVariant === 'critical') ? bannerVariant : undefined,
  )

  if (!bannerMessage || !bannerVariant || !showBanner) return null

  const bannerDescription =
    bannerLink && bannerLink.length > 0 ? (
      <>
        {bannerMessage}{' '}
        <Link href={bannerLink} inline>
          Learn more
        </Link>
      </>
    ) : (
      bannerMessage
    )

  return (
    <SummaryCardBanner
      ref={focusRef}
      tabIndex={-1}
      data-testid="license-status-banner"
      variant={bannerVariant}
      title={bannerMessage}
      aria-label={bannerMessage}
      description={bannerDescription}
      hideTitle
      primaryAction={
        bannerVariant === 'warning' && (
          <Banner.PrimaryAction onClick={handleCreateLicense}>Generate new key</Banner.PrimaryAction>
        )
      }
      onDismiss={bannerVariant !== 'warning' ? () => setShowBanner(false) : undefined}
      role={['critical', 'success'].includes(bannerVariant) ? 'status' : undefined} // Make screen readers announce success and error banners
    />
  )
}

export function MeteredEnterpriseServerLicenses({
  business,
  isOwner,
  consumedEnterpriseLicenses,
  isGhasBundled,
  enableGhasBundleMismatchWarning = false,
  isStafftools = false,
  // eslint-disable-next-line @eslint-react/no-unstable-default-props
  serverLicenses: initialServerLicenses = [],
  auditLogQueryUrl = '',
  isCountryBlocked = false,
}: Props) {
  let meteredServerLicensesBaseUrl = `/enterprises/${business.slug}/metered_server_licenses`
  if (isStafftools) {
    meteredServerLicensesBaseUrl = `/stafftools${meteredServerLicensesBaseUrl}`
  }

  const activeServerLicense = initialServerLicenses?.[0]

  // Determine initial banner state based on priority: expired > expiring soon > GHAS mismatch > seat count mismatch
  const initialBannerState = useMemo(() => {
    // Check license expiration status
    const expirationStatus = getLicenseExpirationStatus(activeServerLicense)

    if (consumedEnterpriseLicenses > 0) {
      if (expirationStatus.isExpired) {
        return {
          show: true,
          variant: 'warning' as BannerVariant,
          message: 'Your license key has expired. Generate a new license key to prevent server interruptions.',
          link: '',
        }
      }
      if (expirationStatus.isExpiringSoon) {
        return {
          show: true,
          variant: 'warning' as BannerVariant,
          message: 'Your license key is about to expire. Generate a new license key to prevent server interruptions.',
          link: '',
        }
      }

      // setup warning banner if there is a mismatch between the active license GHAS bundle state and the current GHEC account bundle state
      const activeLicenseGhasBundled = !(
        activeServerLicense?.code_security_enabled || activeServerLicense?.secret_protection_enabled
      )

      // A customer who has unbundled GHAS will only benefit from cost savings on GHES if they use an unbundled license (and only on GHES 3.17+),
      // so if their active GHES license is not yet unbundled we prompt them here to regenerate their license.
      // In the event that a customer is rebundled (should be very rare), there is no need to regenerate a new bundled license,
      // as the rebundled customer will still be billed appropriately even if GHES still has an unbundled license.
      const activeLicenseGhasBundleMismatch = enableGhasBundleMismatchWarning
        ? activeLicenseGhasBundled && !isGhasBundled
        : false

      if (activeLicenseGhasBundleMismatch) {
        return {
          show: true,
          variant: 'warning' as BannerVariant,
          message:
            'Your Advanced Security license has been unbundled into separate SKUs. Generate a new license to update your Enterprise Server usage.',
          link: 'https://docs.github.com/enterprise-cloud@latest/billing/managing-billing-for-your-products/managing-billing-for-github-advanced-security/migrating-from-ghas-to-cs-and-sp',
        }
      }

      // setup warning banner if there is a mismatch between the active license seat count and the current GHEC user count
      const activeLicenseSeatCountMismatch = activeServerLicense?.seats !== consumedEnterpriseLicenses

      if (activeLicenseSeatCountMismatch) {
        return {
          show: true,
          variant: 'warning' as BannerVariant,
          message:
            'Your license usage for Enterprise Cloud has changed. Generate a new license key to update server licenses.',
          link: '',
        }
      }
    }
    return {show: false, variant: undefined, message: '', link: ''}
  }, [consumedEnterpriseLicenses, activeServerLicense, enableGhasBundleMismatchWarning, isGhasBundled])

  const [serverLicenses, setServerLicenses] = useState(initialServerLicenses)
  const [showBanner, setShowBanner] = useState<boolean>(initialBannerState.show)
  const [bannerMessage, setBannerMessage] = useState<string>(initialBannerState.message)
  const [bannerLink, setBannerLink] = useState<string>(initialBannerState.link)
  const [bannerVariant, setBannerVariant] = useState<BannerVariant | undefined>(initialBannerState.variant)
  const [isGenerating, setIsGenerating] = useState<boolean>(false)
  const {exportJobState, startExport} = useExportStatus(meteredServerLicensesBaseUrl)

  const showAuditLogLink = isStafftools && auditLogQueryUrl.length > 0

  async function handleCreateLicense() {
    setIsGenerating(true)

    const response = await startExport()
    if (exportJobState === ExportJobState.Error || !response) {
      setBannerVariant('critical')
      setBannerMessage('There was an error generating a new server license. Please try again later.')
      setBannerLink('')
      setShowBanner(true)
      setIsGenerating(false)
      return
    }

    setBannerVariant('success')
    setBannerMessage(
      `New server license generated for ${pluralize(
        consumedEnterpriseLicenses,
        'Enterprise Cloud user',
      )}. Upload to your server instance.`,
    )
    setBannerLink('')
    setShowBanner(true)

    setServerLicenses([response?.license, ...serverLicenses])
    setIsGenerating(false)
  }

  async function handleRegenerateLicense(serverLicense: ServerLicense) {
    setIsGenerating(true)
    const response = await verifiedFetch(`${meteredServerLicensesBaseUrl}/${serverLicense.reference_number}`, {
      method: 'PUT',
    })
    if (!response.ok) {
      setBannerVariant('critical')
      setBannerMessage('There was an error regenerating the server license. Please try again later.')
      setBannerLink('')
      setShowBanner(true)
      setIsGenerating(false)
      return
    }

    setBannerVariant('success')
    setBannerMessage('Server license regenerated successfully.')
    setBannerLink('')
    setShowBanner(true)

    setIsGenerating(false)
  }

  return (
    <div className="tmp-mb-4" data-testid="metered-enterprise-server-licenses">
      <SummaryCard
        headerIconComponent={ServerIcon}
        title="Enterprise Server keys"
        /* eslint-disable-next-line @github-ui/dotcom-primer/no-title-case -- baselined during linter rollout */
        headerMenu={showAuditLogLink && <Link href={auditLogQueryUrl}>Audit Log</Link>}
      >
        {isGenerating ? (
          <GeneratingLicense consumedEnterpriseLicenses={consumedEnterpriseLicenses} />
        ) : (
          <DisplayLicenses
            isOwner={isOwner}
            serverLicenses={serverLicenses}
            bannerVariant={bannerVariant}
            showBanner={showBanner}
            bannerMessage={bannerMessage}
            bannerLink={bannerLink}
            handleCreateLicense={handleCreateLicense}
            handleRegenerateLicense={handleRegenerateLicense}
            setShowBanner={setShowBanner}
            consumedEnterpriseLicenses={consumedEnterpriseLicenses}
            meteredServerLicensesBaseUrl={meteredServerLicensesBaseUrl}
            isStafftools={isStafftools}
            isCountryBlocked={isCountryBlocked}
          />
        )}
      </SummaryCard>
    </div>
  )
}

const DisplayLicenses = ({
  isOwner,
  serverLicenses,
  bannerVariant,
  showBanner,
  bannerMessage,
  bannerLink,
  handleCreateLicense,
  handleRegenerateLicense,
  setShowBanner,
  consumedEnterpriseLicenses,
  meteredServerLicensesBaseUrl,
  isStafftools,
  isCountryBlocked,
}: {
  isOwner: boolean
  serverLicenses: ServerLicense[]
  bannerVariant?: BannerVariant
  showBanner: boolean
  bannerMessage?: string
  bannerLink?: string
  handleCreateLicense: () => Promise<void>
  handleRegenerateLicense: (serverLicense: ServerLicense) => Promise<void>
  setShowBanner: Dispatch<SetStateAction<boolean>>
  consumedEnterpriseLicenses: number
  meteredServerLicensesBaseUrl: string
  isStafftools: boolean
  isCountryBlocked: boolean
}) => {
  if (serverLicenses.length === 0) {
    return (
      <>
        {bannerVariant === 'critical' && (
          <MESLBanner
            showBanner={showBanner}
            bannerVariant={bannerVariant}
            bannerMessage={bannerMessage}
            bannerLink={bannerLink}
            handleCreateLicense={handleCreateLicense}
            setShowBanner={setShowBanner}
          />
        )}
        <div className="Box-footer d-flex flex-items-center flex-justify-between border-0">
          <div className={clsx('text-normal ml-1 color-fg-default', styles.noServerKeysMessage)}>
            You don&apos;t have any server keys.
            {consumedEnterpriseLicenses > 0 ? (
              (isOwner || isStafftools) && (
                <>
                  &nbsp;
                  <Link className="Link--inTextBlock cursor-pointer" inline onClick={handleCreateLicense}>
                    Generate new key
                  </Link>
                  .
                </>
              )
            ) : (
              <>
                &nbsp;
                <span data-testid="add-cloud-users-message">
                  Please add users to your Enterprise Cloud account to generate a license
                </span>
                .
              </>
            )}
          </div>
        </div>
      </>
    )
  }

  return (
    <>
      <MESLBanner
        showBanner={showBanner}
        bannerVariant={bannerVariant}
        bannerMessage={bannerMessage}
        bannerLink={bannerLink}
        handleCreateLicense={handleCreateLicense}
        setShowBanner={setShowBanner}
      />
      {serverLicenses.map((serverLicense, i) => (
        <MeteredEnterpriseServerLicense
          key={serverLicense.reference_number}
          serverLicense={serverLicense}
          // Only show the download link for owners and the first license
          showDownloadLink={i === 0 && isOwner}
          showRegenerateLink={isStafftools}
          meteredServerLicensesBaseUrl={meteredServerLicensesBaseUrl}
          onRegenerate={handleRegenerateLicense}
          isCountryBlocked={isCountryBlocked}
        />
      ))}
    </>
  )
}

// Focus the element when the trigger changes. Consider extracting this to a common hook if we need it in more places.
function useFocusOnShow(trigger: string | null | undefined | false): React.RefObject<HTMLDivElement | null> {
  const ref = useRef<HTMLDivElement>(null)
  useEffect(() => {
    if (trigger && ref.current) {
      ref.current.focus()
    }
  }, [trigger])
  return ref
}
